import os,re
d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n')
G={}
for m in re.finditer(r'(Demo pair (\d+) (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
    k,h,w=m[1],int(m[3]),int(m[4])
    rows=[r.split() for r in t[m.end():].split('\n')[:h]]
    if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
        G[k]=[[int(x) for x in r] for r in rows]
print(sorted(G))

from collections import Counter
def transform(g):
    H,W=len(g),len(g[0])
    bg=Counter(x for r in g for x in r).most_common(1)[0][0]
    # find rectangles: connected same-color regions, bbox fully that color except tiny noise
    seen=[[False]*W for _ in range(H)]
    rects=[]
    for i in range(H):
        for j in range(W):
            if seen[i][j]: continue
            c=g[i][j]
            stack=[(i,j)];seen[i][j]=True;cells=[]
            while stack:
                y,x=stack.pop();cells.append((y,x))
                for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                    ny,nx=y+dy,x+dx
                    if 0<=ny<H and 0<=nx<W and not seen[ny][nx] and g[ny][nx]==c:
                        seen[ny][nx]=True;stack.append((ny,nx))
            if len(cells)>=6:
                ys=[y for y,x in cells];xs=[x for y,x in cells]
                rects.append((min(ys),max(ys),min(xs),max(xs),c))
    out=[row[:] for row in g]
    for i in range(H):
        for j in range(W):
            out[i][j]=bg
    for y0,y1,x0,x1,c in rects:
        for i in range(y0,y1+1):
            for j in range(x0,x1+1):
                out[i][j]=c
    return out
print(transform(G['Demo pair 1 input'])==G['Demo pair 1 output'])
